12		<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ctext y='.9em' font-size='90'%3E👋%3C/text%3E%3C/svg%3E">
13		<style>
14			:root {
15				color-scheme: light dark;
16				--text: #1a1a1a;
17				--text-secondary: #555;
18				--background: #fff;
19				--surface: #fff;
20				--accent: #0052a3;
21				--border: #e0e0e0;
22			}
23			@media (prefers-color-scheme: dark) {
24				:root {
25					--text: #e0e0e0;
26					--text-secondary: #a0a0a0;
27					--background: #121212;
28					--surface: #1e1e1e;
29					--accent: #5fa3ff;
30					--border: #333;
31				}
32			}
33			*,
34			*::before,
35			*::after {
36				box-sizing: border-box;
37			}
38			html {
39				-webkit-text-size-adjust: 100%;
40				text-size-adjust: 100%;
41			}
42			@media (prefers-reduced-motion: no-preference) {
43				html {
44					scroll-behavior: smooth;
45				}
46				a {
47					transition: text-decoration-thickness 0.15s ease;
48				}
49				.skip-link {
50					transition: transform 0.15s ease;
51				}
52				button,
53				.button {
54					transition: opacity 0.15s ease, transform 0.15s ease;
55				}
56			}
57			body {
58				display: grid;
59				grid-template-columns: minmax(0, 1fr);
60				grid-template-rows: auto 1fr auto;
61				min-height: 100vh;
62				min-height: 100dvh;
63				font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
64				font-size: 1rem;
65				line-height: 1.6;
66				overflow-wrap: break-word;
67				max-width: 70ch;
68				margin: 0 auto;
69				padding-top: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-top));
70				padding-right: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-right));
71				padding-bottom: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-bottom));
72				padding-left: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-left));
73				color: var(--text);
74				background: var(--background);
75			}
76			h1 {
77				color: var(--accent);
78				font-size: clamp(1.75rem, 1.25rem + 3vw, 2.5rem);
79				font-weight: 700;
80				line-height: 1.1;
81				text-wrap: balance;
82				margin: 0 0 1.5rem 0;
83				letter-spacing: -0.02em;
84			}
85			h2 {
86				color: var(--accent);
87				font-size: clamp(1.25rem, 1rem + 1.5vw, 1.75rem);
88				font-weight: 600;
89				line-height: 1.2;
90				text-wrap: balance;
91				margin: 2rem 0 1rem 0;
92				letter-spacing: -0.01em;
93			}
94			h2:first-child {
95				margin-top: 0;
96			}
97			p {
98				text-wrap: pretty;
99				margin: 1rem 0;
100				line-height: 1.65;
101			}
102			a {
103				color: var(--accent);
104				text-underline-offset: 0.2em;
105				text-decoration-thickness: 2px;
106				text-decoration-skip-ink: auto;
107				font-weight: 500;
108			}
109			a:hover, a:active {
110				text-decoration-thickness: 3px;
111			}
112			button,
113			.button {
114				display: inline-block;
115				text-decoration: none;
116				padding: 0.75rem 1.5rem;
117				font-size: 1rem;
118				font-weight: 500;
119				font-family: inherit;
120				color: var(--background);
121				background: var(--accent);
122				border: 2px solid var(--accent);
123				border-radius: 0.25rem;
124				cursor: pointer;
125				white-space: nowrap;
126			}
127			button:hover,
128			.button:hover {
129				opacity: 0.85;
130				text-decoration: none;
131			}
132			button:active,
133			.button:active {
134				transform: scale(0.97);
135			}
136			ul, ol {
137				margin: 1rem 0;
138				padding-left: 2rem;
139			}
140			li {
141				margin: 0.5rem 0;
142			}
143			:focus-visible {
144				outline: 2px solid var(--accent);
145				outline-offset: 2px;
146			}
147			a:not(.button):focus-visible {
148				border-radius: 2px;
149			}
150			.skip-link {
151				position: absolute;
152				left: 0;
153				top: 0;
154				transform: translateY(-100%);
155				background: var(--accent);
156				color: var(--background);
157				padding: 0.75rem 1.5rem;
158				z-index: 1000;
159				border-radius: 0 0 0.25rem 0;
160				font-weight: 600;
161				text-decoration: none;
162				display: inline-block;
163			}
164			.skip-link:focus {
165				transform: none;
166				outline: 3px solid var(--text);
167				outline-offset: -3px;
168			}
169			header {
170				padding-block: 1.5rem 0;
171			}
172			header nav ul {
173				display: flex;
174				flex-wrap: wrap;
175				gap: 0.5rem 1.5rem;
176				margin: 1rem 0 0 0;
177				padding: 0;
178				list-style: none;
179			}
180			header nav li {
181				margin: 0;
182			}
183			main {
184				padding: 1rem 0;
185			}
186			main:focus {
187				outline: none;
188			}
189			section {
190				margin: 2rem 0;
191			}
192			[id] {
193				scroll-margin-top: 1.5rem;
194			}
195			@media (forced-colors: active) {
196				.skip-link,
197				button,
198				.button {
199					border: 2px solid ButtonText;
200				}
201			}
202			.card {
203				border: 1px solid var(--border);
204				border-radius: 0.5rem;
205				padding: 1.5rem;
206				background: var(--surface);
207				margin: 1.5rem 0;
208			}
209			.card h3 {
210				font-size: 1.25rem;
211				line-height: 1.3;
212				text-wrap: balance;
213				margin-top: 0;
214				margin-bottom: 0.5rem;
215				color: var(--accent);
216			}
217			.visually-hidden {
218				position: absolute;
219				width: 1px;
220				height: 1px;
221				margin: -1px;
222				padding: 0;
223				overflow: hidden;
224				clip: rect(0, 0, 0, 0);
225				white-space: nowrap;
226				border: 0;
227			}
228			@media (prefers-contrast: more) {
229				:root {
230					--border: currentColor;
231				}
232				button,
233				.button {
234					border-width: 3px;
235				}
236				.card {
237					border-width: 2px;
238				}
239			}
240			footer {
241				padding-block: 1.5rem;
242				border-top: 1px solid var(--border);
243				font-size: 0.875rem;
244				color: var(--text-secondary);
245				text-align: center;
246			}
247			footer p {
248				margin: 0.5rem 0;
249			}
250			small {
251				display: block;
252			}
253			.field {
254				margin-bottom: 1rem;
255			}
256			label {
257				display: block;
258				margin-bottom: 0.5rem;
259				font-weight: 500;
260			}
261			input,
262			textarea {
263				width: 100%;
264				padding: 0.5rem;
265				font: inherit;
266				color: var(--text);
267				background: var(--surface);
268				border: 1px solid var(--border);
269				border-radius: 0.25rem;
270			}
271			textarea {
272				resize: vertical;
273			}
274			#form-status:empty {
275				display: none;
276			}
277			.live-region {
278				display: flex;
279				align-items: center;
280				min-height: 3.5rem;
281				margin-top: 1rem;
282				padding: 1rem;
283				border: 1px dashed var(--border);
284				border-radius: 0.25rem;
285			}
286			input:focus,
287			textarea:focus {
288				outline: 2px solid var(--accent);
289				outline-offset: 2px;
290				border-color: var(--accent);
291			}
292			@media print {
293				:root {
294					color-scheme: light;
295					--text: #000;
296					--text-secondary: #333;
297					--background: #fff;
298					--surface: #fff;
299					--accent: #000;
300					--border: #999;
301				}
302				.skip-link,
303				button,
304				.button {
305					display: none;
306				}
307				body {
308					display: block;
309					min-height: 0;
310					max-width: none;
311					padding: 0;
312				}
313				a {
314					color: inherit;
315					text-decoration: underline;
316				}
317				a[href^="http"]::after {
318					content: " (" attr(href) ")";
319					font-size: 0.85em;
320					font-weight: normal;
321				}
322				.card {
323					border: none;
324					break-inside: avoid;
325				}
326			}
327		</style>
328	</head>
329	<body>
330		<a class="skip-link" href="#main">Skip to content</a>
331		<header>
332			<h1>Welcome</h1>
333			<nav aria-label="Page sections">
334				<ul>
335					<li><a href="#features">Features</a></li>
336					<li><a href="#examples">Examples</a></li>
337					<li><a href="#resources">Resources</a></li>
338				</ul>
339			</nav>
340		</header>
341		<main id="main" tabindex="-1">
342			<section aria-label="Introduction">
343				<p>This is a well-structured, accessible HTML5 document demonstrating modern best practices for semantic markup and inclusive design.</p>
344				<p>
345					It uses semantic landmarks, a skip link for keyboard navigation,
346					and CSS that adapts to your light or dark mode preference.
347				</p>
348				<p>
349					Text and link colors meet WCAG AA contrast in both themes, type scales
350					with your browser's font size, and motion respects your system settings.
351				</p>
352			</section>
353	
354			<section aria-labelledby="features">
355				<h2 id="features">Features</h2>
356				<ul>
357					<li>Semantic HTML structure with proper landmarks</li>
358					<li>Keyboard accessible navigation and focus management</li>
359					<li>Dark mode support with custom color schemes</li>
360					<li>Responsive typography using modern CSS</li>
361					<li>Print-friendly styles for better readability</li>
362					<li>WCAG AA contrast compliance in all color modes</li>
363				</ul>
364			</section>
365	
366			<section aria-labelledby="examples">
367				<h2 id="examples">Examples</h2>
368				<article class="card">
369					<h3>Component Cards</h3>
370					<p>Card components are useful for organizing related content. They include a subtle border and padding for visual separation.</p>
371					<a class="button" href="#resources">Learn more<span class="visually-hidden"> about accessibility resources</span></a>
372				</article>
373	
374				<article class="card">
375					<h3>Interactive Elements</h3>
376					<p>Buttons and links are fully accessible with clear focus states. The “Learn more” button above demonstrates smooth transitions and proper visual feedback.</p>
377					<p>Try using the Tab key to navigate through all interactive elements.</p>
378				</article>
379	
380				<article class="card">
381					<h3>Accessible Form</h3>
382					<form id="contact-form">
383						<div class="field">
384							<label for="email">Email <span aria-hidden="true">*</span><span class="visually-hidden"> (required)</span></label>
385							<input type="email" id="email" name="email" autocomplete="email" required>
386						</div>
387						<div class="field">
388							<label for="message">Message</label>
389							<textarea id="message" name="message" rows="4"></textarea>
390						</div>
391						<button type="submit">Send message</button>
392						<p id="form-status" role="status"></p>
393					</form>
394				</article>
395	
396				<article class="card">
397					<h3>Live Region Example</h3>
398					<p>Click the button to announce a message using a live region. This demonstrates how screen readers are notified of dynamic updates.</p>
399					<button id="announce" type="button">Announce message</button>
400					<div class="live-region" aria-live="polite" aria-atomic="true">
401						<span id="live-message"></span>
402					</div>
403				</article>
404			</section>
405	
406			<section aria-labelledby="resources">
407				<h2 id="resources">Resources</h2>
408				<p>Want to learn more about web accessibility and semantic HTML? Check out these resources:</p>
409				<ul>
410					<li><a href="https://www.w3.org/WAI/WCAG22/quickref/" target="_blank" rel="noopener noreferrer">WCAG 2.2 Quick Reference<span class="visually-hidden"> (opens in new tab)</span></a></li>
411					<li><a href="https://html.spec.whatwg.org/" target="_blank" rel="noopener noreferrer">HTML Living Standard<span class="visually-hidden"> (opens in new tab)</span></a></li>
412					<li><a href="https://www.a11y-101.com/" target="_blank" rel="noopener noreferrer">A11y 101<span class="visually-hidden"> (opens in new tab)</span></a></li>
413				</ul>
414			</section>
415		</main>
416		<footer>
417			<p><small>&copy; <time datetime="2026">2026</time>. All rights reserved.</small></p>
418			<p><a href="#top">Back to top</a></p>
419		</footer>
420		<script>
421			const messages = [
422				"This update was announced to screen readers!",
423				"Dynamic content updates work with aria-live regions.",
424				"Live regions are essential for accessible web apps.",
425				"Try this with a screen reader like NVDA or JAWS!"
426			];
427			let nextMessage = 0;
428			document.getElementById('announce').addEventListener('click', () => {
429				document.getElementById('live-message').textContent = messages[nextMessage];
430				nextMessage = (nextMessage + 1) % messages.length;
431			});
432			document.getElementById('contact-form').addEventListener('submit', (event) => {
433				event.preventDefault();
434				document.getElementById('form-status').textContent = "Thanks! This is a demo, so nothing was sent.";
435			});
436		</script>
437	</body>
438	</html>
